provider "aws" {
  region = "us-west-2"
}

resource "aws_route53_zone" "private" {
  name = "private.example.com"
}

resource "aws_route53_zone" "public" {
  name = "public.example.com"
}

resource "aws_rds_instance" "internal" {
  engine              = "mysql"
  engine_version       = "8.0.23"
  instance_class     = "t3.micro"
  allocated_storage   = 20
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "internal-db"
  }
}

resource "aws_rds_instance" "public" {
  engine              = "mysql"
  engine_version       = "8.0.23"
  instance_class     = "t3.micro"
  allocated_storage   = 20
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "public-db"
  }
}

resource "aws_db_subnet_group" "main" {
  name        = "main-subnet-group"
  subnet_ids = [aws_subnet.main.id]
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block         = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_security_group" "rds_sg" {
  name        = "rds-sg"
  description = "Security group for RDS instances"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

This Terraform program creates the necessary AWS resources to configure Route 53 to route traffic to different database endpoints based on whether the user is internal or external. It includes a VPC, subnets, RDS instances, and a security group for the RDS instances. The Route 53 zones and records are configured to direct traffic to the appropriate RDS instance based on the domain name.

