  description     = "A bot to assist with ordering pizzas"
  detect_sentiment = false
  enable_model_improvements = false

  intent {
    intent_name = "OrderPizzaIntent"
    intent_version = "1"
  }

  clarification_prompt {
    max_attempts = 3
    response_card = jsonencode({
      version = "1.0"
      contentType = "application/vnd.amazonaws.console.template.v1"
      title = "Clarification Needed"
      cardContent = {
        type = "Standard"
        title = "We need more information"
        subtitle = "Please provide your order details."
        text = "Could you please specify what kind of pizza you would like to order?"
        buttons = [
          {
            text = "Cancel"
            value = "cancel"
          },
          {
            text = "Yes"
            value = "yes"
          }
        ]
      }
    })
  }

  abort_statement {
    response_card = jsonencode({
      version = "1.0"
      contentType = "application/vnd.amazonaws.console.template.v1"
      title = "Order Aborted"
      cardContent = {
        type = "Standard"
        title = "Order Aborted"
        subtitle = "Your order has been cancelled."
        text = "Thank you for using our pizza ordering service."
        buttons = [
          {
            text = "OK"
            value = "ok"
          }
        ]
      }
    })
  }

  conclusion_statement {
    response_card = jsonencode({
      version = "1.0"
      contentType = "application/vnd.amazonaws.console.template.v1"
      title = "Order Confirmation"
      cardContent = {
        type = "Standard"
        title = "Order Confirmation"
        subtitle = "Your order has been placed."
        text = "Thank you for choosing our pizza ordering service."
        buttons = [
          {
            text = "OK"
            value = "ok"
          }
        ]
      }
    })
  }
}
