  retention_period = 24
  shard_count = 1
}

resource "aws_redshift_cluster" "my_redshift_cluster" {
  cluster_identifier = "my-redshift-cluster"
  node_type = "dc2.large"
  cluster_parameter_group_name = "default.redshift-6.x"
  cluster_subnet_group_name = "my-redshift-subnet-group"
  availability_zone = "us-west-2a"
  automated_snapshot_retention_period = 7
  cluster_version = "13.2"
  database_name = "my_database"
  default_iam_role_arn = "arn:aws:iam::123456789012:role/my-redshift-role"
  encrypted = true
  kms_key_id = "arn:aws:kms:us-west-2:123456789012:key/my-redshift-key"

  logging {
    enable = true
    bucket_name = "my-redshift-logs.s3.amazonaws.com"
    log_destination_type = "s3"
    log_exports = ["INFO", "ERROR"]
    s3_key_prefix = "redshift/"
  }

  snapshot_copy {
    destination_region = "us-east-1"
    grant_name = "my-redshift-snapshot-grant"
    retention_period = 30
  }
}

resource "aws_kinesis_firehose_delivery_stream" "my_kinesis_firehose" {
  name = "my_kinesis_firehose"
  destination = "redshift"

  redshift_configuration {
    cluster_jdbcurl = aws_redshift_cluster.my_redshift_cluster.endpoint
    data_table_name = "my_table"
    role_arn = aws_redshift_cluster.my_redshift_cluster.default_iam_role_arn
    copy_options = "DELIMITER ','"
    data_table_columns = "column1,column2,column3"
    password = "my_password"
    username = "my_username"
  }

  tags = {
    Name = "my-kinesis-firehose"
  }
}
