      Statement = [
        {
          Action = [
            "s3:GetObject",
            "s3:GetObjectVersion"
          ]
          Effect = "Allow"
          Resource = "arn:aws:s3:::my-bucket/*"
        }
      ]
    })
  }

  timeouts {
    create = "30m"
    delete = "30m"
  }
}

resource "aws_kendra_data_source" "kendra_data_source" {
