  name           = "kendra-data-source"
  type           = "s3"
  role_arn       = aws_iam_role.kendra_data_source_role.arn
  description    = "Kendra data source for proxy configuration"
  language_code  = "en"
  schedule       = "cron(0 0 * * ? *)"
  tags           = {
    Environment = "Development"
  }
  tags_all        = {
    Environment = "Development"
