  name     = "${var.workspace_name}-eks-cluster"
  role_arn = aws_iam_role.eks_role.arn

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controller-manager", "scheduler"]

  vpc_config {
    subnet_ids = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    endpoint_private_access = true
    endpoint_public_access = true
    public_access_cidrs = ["0.0.0.0/0"]
    security_group_ids = ["sg-12345678"]
  }

  compute_config {
    node_pools {
      name          = "default"
      instance_types = ["t3.micro"]
      node_role_arn = aws_iam_role.node_role.arn
      desired_size = 3
      max_size     = 5
      min_size     = 2
    }
  }

  encryption_config {
    resources = ["secrets"]
    kms_key   = aws_kms_key.eks_key.arn
  }

  timeouts {
    create = "60m"
    delete = "60m"
    update = "60m"
  }
}

resource "aws_eks_auth_config_map" "eks_auth_config_map" {
  name = "${var.workspace_name}-eks-auth-config-map"

  data = {
    "cluster-ca.crt" = base64encode(data.aws_caller_identity.caller_identity.certificate_authority.data)
    "token"         = data.aws_eks_cluster.eks_cluster.token
  }
}

provider "helm" {
  kubernetes {
    host     = data.aws_eks_cluster.eks_cluster.endpoint
    namespace = "default"
    cluster_ca_certificate = base64decode(data.aws_caller_identity.caller_identity.certificate_authority.data)
    token     = data.aws_eks_cluster.eks_cluster.token
  }
}

provider "kubernetes" {
  host     = data.aws_eks_cluster.eks_cluster.endpoint
  namespace = "default"
  cluster_ca_certificate = base64decode(data.aws_caller_identity.caller_identity.certificate_authority.data)
  token     = data.aws_eks_cluster.eks_cluster.token
}
```

### Explanation:
- **AWS Provider**: Configured for the `us-west-2` region.
- **Caller Identity**: Retrieves the current AWS caller identity.
- **SSM Parameters**: Defines SSM parameters for the image tag, AWS tags, and workspace name with realistic offline-valid default values.
- **EKS Cluster**: Creates an EKS cluster with the specified configuration, including VPC settings, compute pools, encryption, and timeouts.
- **EKS Auth Config Map**: Generates an auth config map for Kubernetes to authenticate with the EKS cluster.
- **Helm and Kubernetes Providers**: Configures Helm and Kubernetes providers with the EKS cluster's details for cluster communication.

