provider "aws" {
  region = "us-west-2"  # Replace with your desired AWS region
}

resource "aws_iam_role" "eks_fargate_role" {
  name = "eks-fargate-profile-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks-fargate-pods.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AmazonEKSFargatePodExecutionRole"
  ]

  tags = {
    Name = "eks-fargate-role"
  }
}

resource "aws_eks_fargate_profile" "main" {
  cluster_name = "my-eks-cluster"  # Replace with your EKS cluster name
  fargate_profile_name = "eks-fargate-profile-example"
  pod_execution_role_arn = aws_iam_role.eks_fargate_role.arn

  subnet_ids = ["subnet-12345678", "subnet-23456789"]  # Replace with your subnet IDs
}

resource "aws_eks_pod_identity_association" "main" {
  cluster_name = "my-eks-cluster"  # Replace with your EKS cluster name
  namespace = "default"
  role_arn = aws_iam_role.eks_fargate_role.arn
  service_account = "default"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`. You can change this to any valid AWS region.
- **IAM Role**: An IAM role named `eks-fargate-profile-example` is created with the specified assume role policy and managed policy. The `managed_policy_arns` includes the Amazon EKS Fargate Pod Execution Role Policy.
- **EKS Fargate Profile**: An EKS Fargate profile named `eks-fargate-profile-example` is created for the specified EKS cluster. It uses the IAM role created above and specifies the subnet IDs where the pods will run.
- **EKS Pod Identity Association**: A pod identity association is created to associate the EKS Fargate profile with a service account in the specified namespace. This allows the pods to assume the IAM role for authentication and authorization.

