  region = "us-west-2"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier     = "redshift-cluster-1"
  node_type             = "dc2.large"
  master_username       = "admin"
  master_password       = "SecurePassword123!"
  db_name               = "mydatabase"
  cluster_parameter_group_name = "default.redshift-6.x"
  cluster_subnet_group_name = "default"
  vpc_security_group_ids = ["sg-12345678"]
  iam_roles              = ["arn:aws:iam::123456789012:role/redshift-role"]

  tags = {
    Name = "Redshift Cluster"
  }
}

resource "aws_redshift_resource_policy" "main" {
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "AllowRedshiftAccess"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::my-redshift-bucket/*"
        ]
      }
    ]
  })

  resource_arn = aws_redshift_cluster.redshift_cluster.arn
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **Redshift Cluster**: 
  - `cluster_identifier`: A unique identifier for the Redshift cluster.
  - `node_type`: Specifies the type of node to use, `dc2.large` in this case.
  - `master_username` and `master_password`: Credentials for the master user.
  - `db_name`: The name of the default database.
  - `cluster_parameter_group_name`: Uses the default parameter group for Redshift 6.x.
  - `cluster_subnet_group_name`: Uses the default subnet group.
  - `vpc_security_group_ids`: References an existing security group (`sg-12345678`) to control access.
  - `iam_roles`: Attaches an IAM role (`arn:aws:iam::123456789012:role/redshift-role`) for authentication.
  - `tags`: Adds a tag to the cluster for easy identification.
- **Redshift Resource Policy**:
  - Defines a policy that allows Redshift to access an S3 bucket (`my-redshift-bucket`) for logging purposes.
  - The policy is applied to the Redshift cluster using the `resource_arn` attribute.

