provider "aws" {
  region = "us-west-2"
}

resource "aws_api_gateway_rest_api" "rest_api" {
  name = "lightsail-db-integration-api"
}

resource "aws_api_gateway_resource" "main" {
  rest_api_id = aws_api_gateway_rest_api.rest_api.id
  parent_id   = aws_api_gateway_rest_api.rest_api.root_resource_id
  path_part   = "lightsail-database"
}

resource "aws_api_gateway_integration" "lightsail_database_integration" {
  rest_api_id           = aws_api_gateway_rest_api.rest_api.id
  resource_id           = aws_api_gateway_resource.main.id
  http_method           = "GET"
  type                 = "AWS_PROXY"
  integration_http_method = "POST"
  uri                  = "https://lightsail.amazonaws.com/v2016-11-28/databases/${aws_lightsail_database.main.name}/query"
  passthrough_behavior = "WHEN_NO_MATCH"
  request_templates     = jsonencode({
    "application/json" = "{\"query\": \"$input.body\"}"
  })
  cache_key_parameters = ["method.request.path"]
  cache_ttl             = 300
}
```

This Terraform program creates an AWS API Gateway REST API, a resource within that API, and an integration that forwards GET requests to a Lightsail database. The integration uses a POST method to the Lightsail database's query endpoint, passing the request body as JSON. The integration is configured with caching enabled to improve performance.

