provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk_logs_bucket-${random_string.random_suffix.result}"
  acl    = "private"

  tags = {
    Name = "MSK Logs Bucket"
  }
}

resource "aws_s3_bucket_logging" "msk_logs_bucket" {
  bucket = aws_s3_bucket.msk_logs_bucket.bucket
  target_bucket = aws_s3_bucket.msk_logs_bucket.bucket
  target_prefix = "logs/"

  target_grant {
    grantee {
      type = "CanonicalUser"
      uri = "arn:aws:iam::123456789012:user/example-user"
    }
    permission = "FULL_CONTROL"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = "msk-cluster-${random_string.random_suffix.result}"
  kafka_version = "2.8.2"
  number_of_broker_nodes = 3

  logging {
    enabled = true
    bucket = aws_s3_bucket_logging.msk_logs_bucket.bucket
    prefix = "logs/"
  }

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    instance_type = "t3.micro"
    security_groups = ["sg-12345678"]

    az_distribution = "DEFAULT"
  }

  client_authentication {
    unauthenticated = false
  }

  configuration_info {
    arn = "arn:aws:kafka:us-east-1:123456789012:configuration/msk-config/12345678901234567890"
    revision = 1
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-east-1:123456789012:key/12345678-1234-1234-1234-123456789012"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
}
```

This Terraform program creates a managed MSK cluster in `us-east-1` with logging to an S3 bucket. It includes a random suffix for resource names to ensure uniqueness. The S3 bucket is configured with logging to the MSK cluster's logs, and the MSK cluster is configured with basic authentication and encryption.

