# Security group to allow inbound traffic on port 5432 from anywhere
resource "aws_security_group" "allow_postgres_traffic" {
  name        = "allow-postgres-traffic"
  description = "Allow inbound traffic on port 5432 from anywhere"

  ingress {
    cidr_blocks = ["0.0.0.0/0"]
    from_port   = 5432
    protocol   = "-1"
    to_port     = 5432
  }

  egress {
    cidr_blocks = ["0.0.0.0/0"]
    from_port   = 0
    protocol   = "-1"
    to_port     = 0
  }
}

# Associate the security group with the RDS cluster
resource "aws_db_security_group_association" "associate_security_group" {
  db_security_group_id = aws_security_group.allow_postgres_traffic.id
  db_instance_identifier = aws_rds_cluster.my_aurora_postgres_cluster.id
}
