resource "aws_s3_bucket_notification" "log_notification_config" {
  bucket = aws_s3_bucket.my_log_bucket.bucket

  lambda_function {
    events     = ["s3:ObjectCreated:*"]
    function_arn = aws_lambda_function.log_notification_lambda.function_arn
  }
}

resource "aws_lambda_function" "log_notification_lambda" {
  filename      = "lambda_function.zip"
  function_name = "log_notification_lambda"
  handler       = "index.handler"
  runtime       = "python3.8"

  role = aws_iam_role.lambda_execution_role.arn

  source_code_hash = filebase64sha256("lambda_function.zip")

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.my_log_bucket.bucket
    }
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role-${random_string.random_suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "lambda-execution-policy-${random_string.random_suffix.result}"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Effect = "Allow"
          Resource = "arn:aws:logs:${var.aws_region}:${var.aws_account_id}:log-group:/aws/lambda/${aws_lambda_function.log_notification_lambda.function_name}*"
        }
      ]
    })
  }
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
}
```

