provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "cs_class_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
  tags = {
    Name = "cs-class-vpc"
  }
}

resource "aws_iam_role" "cs_class_autograder_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "cs-class-autograder-role"
  }
}

resource "aws_iam_role_policy_attachment" "cs_class_autograder_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRolePolicy"
  role = aws_iam_role.cs_class_autograder_role.name
}

resource "aws_s3_bucket" "cs_class_results_bucket" {
  bucket = "cs-class-results-bucket-${random_string.random_suffix.result}"
  acl = "private"
  tags = {
    Name = "cs-class-results-bucket"
  }
}

resource "aws_secretsmanager_secret" "cs_class_github_token" {
  name = "cs-class-github-token"

  secret_string = jsonencode({
    token = "your-github-token-here"
  })

  tags = {
    Name = "cs-class-github-token"
  }
}

resource "aws_codebuild_project" "cs_class_autograder" {
  name = "cs-class-autograder"

  service_role = aws_iam_role.cs_class_autograder_role.arn

  vpc_config {
    vpc_id = aws_vpc.cs_class_vpc.id
    subnet_ids = aws_subnet.cs_class_subnets[*].id
    security_group_ids = aws_security_group.cs_class_security_groups[*].id
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.cs_class_results_bucket.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type = "LINUX_CONTAINER"
  }

  environment_variables = [
    {
      name = "GITHUB_TOKEN"
      value = aws_secretsmanager_secret.cs_class_github_token.arn
      type = "PLAINTEXT"
    }
  ]

