  force_destroy = true
}

resource "aws_codebuild_project" "cs_class_autograder" {
  name            = "cs-class-autograder"
  service_role     = aws_iam_role.codebuild_service_role.arn
  badge_enabled   = false
  build_timeout   = 60
  concurrent_build_limit = 1
  description    = "Automated grading system for CS class"
  encryption_key = aws_kms_key.codebuild_encryption_key.arn
  source         {
    type          = "GitHub"
    location      = "https://github.com/example/cs-class.git"
    git_clone_depth = 1
    insecure_ssl   = true
    report_build_status = true
  }
  artifacts {
    type          = "S3"
    location      = aws_s3_bucket.autograder_results.bucket
    namespace_type = "NONE"
    packaging     = "ZIP"
    path          = "results"
  }
  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image         = "aws/codebuild/standard:5.0"
    type         = "LINUX_CONTAINER"
  }
  vpc_config {
    security_group_ids = [aws_security_group.cs_class_sg.id]
    subnets           = [aws_subnet.cs_class_subnet.id]
    vpc_id            = aws_vpc.cs_class_vpc.id
  }
}

resource "aws_vpc" "cs_class_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

resource "aws_subnet" "cs_class_subnet" {
  vpc_id            = aws_vpc.cs_class_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "cs_class_sg" {
  name        = "cs-class-autograder-sg"
  description = "Security group for the autograder"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Allow SSH access from anywhere
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"] # Allow all outbound traffic
  }
}

