  code_repository_name = "daily-code-repo"

  git_config {
    repository_url = "https://github.com/example/daily-code.git"
    branch         = "main"
  }
}

resource "aws_lambda_function" "daily_code_execution" {
  function_name = "daily-code-execution"
  role          = aws_iam_role.lambda_execution_role.arn

  handler       = "index.handler"
  runtime       = "python3.8"
  timeout       = 30

  code {
    s3_bucket = aws_s3_bucket.daily_code_bucket.bucket
    s3_key   = "index.py"
  }

  environment {
    variables = {
      REPOSITORY_URL = aws_sagemaker_code_repository.main.git_config.repository_url
      BRANCH         = aws_sagemaker_code_repository.main.git_config.branch
    }
  }

  vpc_config {
    security_group_ids = [aws_security_group.lambda_sg.id]
    subnet_ids         = [aws_subnet.public_subnet.id]
  }
}

resource "aws_cloudwatch_event_rule" "daily_code_run" {
  name        = "daily-code-run"
  schedule_expression = "cron(0 7 * * ? *)"

  targets = [
    {
      arn = aws_lambda_function.daily_code_execution.arn
    }
  ]
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

