  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_s3_bucket" "daily_code_bucket" {
  bucket = "daily-code-bucket-${random_string.random_suffix.result}"
  acl     = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_random_string" "random_suffix" {
  length = 8
  special = false
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda-sg"
  description = "Security group for Lambda function"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

