        header_name = "X-Custom-Header"
        header_value = "CustomValue"
      }
    }

    remove_headers {
      header {
        header_name = "X-CloudFront-Forwarded-Proto"
      }
    }

    query_strings_config {
      query_string_behavior = "all"
    }
  }
}
