  vpc_id     = aws_vpc.video_streaming_vpc.id
  cidr_block = cidrsubnet(aws_vpc.video_streaming_vpc.cidr_block, 8, count.index + 1)

  tags = {
    Name = "video-streaming-subnet-${count.index}"
  }
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  subnets             = aws_subnet.video_streaming_subnets[*].id
  internal           = false
  load_balancer_type = "application"

  access_logs {
    bucket = "video-streaming-lb-access-logs"
    enabled = true
    prefix  = "logs/"
  }

  connection_logs {
    bucket = "video-streaming-lb-connection-logs"
    enabled = true
    prefix  = "logs/"
  }

  timeouts {
    create = "60m"
    delete = "60m"
    update = "60m"
  }
}

resource "aws_lb_target_group" "video_streaming_target_group" {
  name     = "video-streaming-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = 80
    interval            = 30
    timeout              = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  stickiness {
    type = "lb_cookie"
    cookie_duration = 86400
  }
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = 80
  protocol           = "HTTP"

  default_action {
    target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
    type             = "forward"
  }
}

resource "aws_instance" "video_streaming_ec2_instances" {
  count = 3

  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t3.micro"
  key_name       = "my-key-pair"          # Replace with your key pair name
  security_groups = ["default"]            # Replace with your security group name
  subnet_id      = aws_subnet.video_streaming_subnets[count.index].id

  tags = {
    Name = "video-streaming-instance-${count.index}"
  }
}

resource "aws_lb_target_group_attachment" "video_streaming_target_group_attachments" {
  count = length(aws_instance.video_streaming_ec2_instances)

  target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  target_id        = aws_instance.video_streaming_ec2_instances[count.index].id
}
