  engine_name       = "sqlserver-ee"
  major_engine_version = "11"
  name              = "option-group-pike"
  name_prefix       = "option-group-pike-"
  option_group_description = "Option group for SQL Server EE"

  option {
    option_name = "SQLSERVER_AUDIT"
    option_settings {
      value = jsonencode({
