provider "aws" {
  region = "us-east-1"
}

resource "aws_lightsail_database" "lightsail_mysql_db" {
  blueprint_id   = "mysql_ami_ami-0c55b159cbfafe1f0"
  bundle_id       = "nano_1gb"
  master_database_name = "mydb"
  master_password = "securepassword123"
  master_username = "admin"
  relational_database_name = "lightsail_mysql_db"
  apply_immediately = true
  availability_zone = "us-east-1a"
  backup_retention_enabled = true
  final_snapshot_name = "lightsail_mysql_db_backup"
  preferred_backup_window = "00:00-01:00"
  preferred_maintenance_window = "17:00-17:30"
  publicly_accessible = false
  skip_final_snapshot = false
  tags = {
    Name = "lightsail-mysql-db"
  }
}

resource "aws_backup_vault" "lightsail_backup_vault" {
  name = "lightsail-backup-vault"
  force_destroy = true
  tags = {
    Name = "lightsail-backup-vault"
  }
}

resource "aws_backup_plan" "lightsail_backup_plan" {
  name = "lightsail-backup-plan"

  advanced_backup_setting {
    backup_options {
      backup_type = "FULL"
    }
    resource_type = "RELATIONAL_DATABASE"
  }

  rule {
    rule_name = "daily-backup-rule"
    target_vault_name = aws_backup_vault.lightsail_backup_vault.name
    schedule_expression_timezone = "UTC"
    schedule_expression = "cron(0 16 * * ? *)"
    start_window = "00:00"
    completion_window = "01:00"
    enable_continuous_backup = false
    recovery_point_tags = {
      BackupType = "Daily"
    }
  }
}
