```hcl
provider "aws" {
  region = "us-west-2"
}

variable "subnet_ids" {
  type = list(string)
  default = ["subnet-12345678", "subnet-87654321"]
}

resource "aws_lb" "gateway_load_balancer" {
  name               = "my-gateway-load-balancer"
  subnets             = var.subnet_ids
  availability_zones = aws_subnet.subnet_ids[*].availability_zone

  access_logs {
    bucket = "my-access-logs-bucket"
    enabled = true
    prefix = "lb-logs/"
  }

  connection_draining {
    enabled = true
    timeout = 300
  }

  cross_zone_load_balancing = true
  enable_http2              = true
  idle_timeout             = 600

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "tcp"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_subnet" "subnet" {
  count = length(var.subnet_ids)

  cidr_block          = cidrsubnet("10.0.0.0/16", 8, count.index)
  availability_zone = var.subnet_ids[count.index]
  vpc_id             = aws_vpc.vpc.id

  tags = {
    Name = "my-subnet-${count.index}"
  }
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "my-vpc"
  }
}
```

This Terraform program creates a Gateway Load Balancer with the specified configuration. It includes a VPC and subnets, and sets up access logs and connection draining. The `subnet_ids` variable can be customized with your own subnet IDs.

